SELECT cp.cp_department, w.w_state, SUM(cs.cs_ext_sales_price) AS total_sales, AVG(cs.cs_net_profit) AS avg_profit FROM catalog_sales cs JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk WHERE cp.cp_type = 'monthly' AND w.w_country = 'United States' GROUP BY cp.cp_department, w.w_state ORDER BY total_sales DESC LIMIT 500
